import { Column, Entity, PrimaryColumn } from 'typeorm';

/** A walk-in customer without an account. The id is generated by the device, so it can be created offline. */
@Entity('cliente_mostrador')
export class ClienteMostradorEntity {
  @PrimaryColumn('uuid')
  id: string;

  @Column({ type: 'uuid', name: 'tenant_id' })
  tenantId: string;

  @Column({ type: 'varchar', length: 80 })
  nombre: string;

  @Column({ type: 'varchar', length: 80, nullable: true })
  apellido: string | null;

  @Column({ type: 'varchar', length: 20, nullable: true })
  celular: string | null;

  @Column({ type: 'varchar', length: 20, nullable: true })
  ci: string | null;

  @Column({ type: 'varchar', length: 120, nullable: true })
  correo: string | null;

  @Column({ type: 'timestamp', name: 'creado_en', default: () => 'NOW()' })
  creadoEn: Date;
}
